<template>
  <section class="business-review" :class="{'is-presenting':presenting}" :role="presenting?'dialog':undefined" :aria-modal="presenting?'true':undefined" aria-label="业务定义与关系评审" data-testid="business-review">
    <header class="review-header">
      <div><span class="review-eyebrow">SUNNYFIT · REQUIREMENTS REVIEW</span><h2>权益、组合与购买的业务关系</h2><p>点击节点查看定义、示例和规则，再打开对应配置核对。依据 <a href="https://sunnyfit.atlassian.net/wiki/x/CQAadg" target="_blank" rel="noopener noreferrer">Entitlement Item List v10 · 2026-10-14</a>。</p></div>
      <div class="review-actions"><el-button @click="copyLink">复制当前视图链接</el-button><el-button data-testid="export-business-svg" @click="exportSvg">导出当前图 SVG</el-button><el-button ref="presentButton" data-testid="present-business-review" :type="presenting?'primary':''" @click="togglePresentation">{{ presenting?'退出演示 · Esc':'演示模式' }}</el-button></div>
    </header>
    <p v-if="feedback" class="review-feedback" role="status">{{ feedback }}</p>
    <div v-if="shareFallback" class="review-share"><label for="review-share-link">当前视图链接</label><input id="review-share-link" :value="shareFallback" readonly @focus="$event.target.select()" /></div>
    <nav class="review-topics" aria-label="业务评审主题"><button v-for="item in topics" :key="item.id" type="button" :class="{active:item.id===topicId}" :aria-pressed="item.id===topicId" :data-testid="'review-topic-'+item.id" @click="selectTopic(item.id)">{{ item.name }}</button></nav>
    <div class="review-topic-heading"><div><h3>{{ topic.title }}</h3><p>{{ topic.description }}</p></div><div class="review-legend" aria-label="关系状态"><span><i class="confirmed"/>已确认</span><span><i class="open"/>Open · 待定</span><span><i class="legacy"/>历史兼容</span></div></div>
    <section class="review-diagram-panel">
      <div class="review-diagram-tools"><span>箭头标注配置引用、组合或交付关系；虚线表示待定。</span><div><el-button size="mini" :disabled="zoom===0.75" aria-label="缩小关系图" @click="changeZoom(-0.25)">−</el-button><span class="review-zoom">{{ zoom===null?'适应':Math.round(zoom*100)+'%' }}</span><el-button size="mini" :disabled="zoom===1.5" aria-label="放大关系图" @click="changeZoom(0.25)">＋</el-button><el-button size="mini" @click="zoom=null">适应画布</el-button></div></div>
      <div class="review-diagram-scroll" tabindex="0" aria-label="关系图画布，可横向滚动" data-testid="business-graph-scroll">
        <svg ref="graphSvg" class="review-graph" :style="zoom===null?{}:{width:topic.width*zoom+'px'}" :viewBox="'0 0 '+topic.width+' '+topic.height" role="group" :aria-label="topic.title" xmlns="http://www.w3.org/2000/svg" data-testid="business-graph">
          <title>{{ topic.title }}</title><desc>{{ topic.description }}</desc>
          <defs><marker v-for="kind in ['confirmed','open','active']" :id="'review-arrow-'+topicId+'-'+kind" :key="kind" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" :fill="kind==='open'?'#b77412':kind==='active'?'#2474c8':'#9caabd'"/></marker></defs>
          <rect :width="topic.width" :height="topic.height" fill="#fff" />
          <text x="32" y="34" fill="#263449" font-family="Segoe UI, Microsoft YaHei, sans-serif" font-size="18" font-weight="600">{{ topic.name }} · {{ topic.title }}</text>
          <g :transform="'translate('+(topic.width-310)+' 49)'" aria-hidden="true"><rect width="9" height="9" fill="#76a8da"/><text x="15" y="9" fill="#63768d" font-size="11" font-family="Segoe UI, Microsoft YaHei, sans-serif">已确认</text><rect x="81" width="9" height="9" fill="#e0ad5a"/><text x="96" y="9" fill="#63768d" font-size="11" font-family="Segoe UI, Microsoft YaHei, sans-serif">Open · 待定</text><rect x="192" width="9" height="9" fill="#a68abd"/><text x="207" y="9" fill="#63768d" font-size="11" font-family="Segoe UI, Microsoft YaHei, sans-serif">历史兼容</text></g>
          <g v-for="(edge,index) in edges" :key="index" aria-hidden="true"><path :d="edge.path" fill="none" :stroke="edgeColor(edge)" stroke-width="2" :stroke-dasharray="edge.status==='open'?'6 5':undefined" :marker-end="'url(#review-arrow-'+topicId+'-'+(edge.status==='open'?'open':edgeActive(edge)?'active':'confirmed')+')'"/><text v-for="(line,lineIndex) in edge.lines" :key="lineIndex" :x="edge.labelX" :y="edge.labelY+lineIndex*15" text-anchor="middle" fill="#5b687b" font-size="12" font-family="Segoe UI, Microsoft YaHei, sans-serif" stroke="#fff" stroke-width="5" paint-order="stroke">{{ line }}</text></g>
          <g v-for="node in topic.nodes" :key="node.id" class="review-graph-node" role="button" tabindex="0" :aria-label="nodeLabel(node)" :aria-pressed="selectedId===node.id" :data-testid="'review-node-'+node.id" @click="selectNode(node.id)" @keydown.enter.prevent="selectNode(node.id)" @keydown.space.prevent="selectNode(node.id)">
            <title>{{ nodeLabel(node) }}</title>
            <rect class="review-node-box" :x="node.x" :y="node.y" :width="node.width" :height="node.height" rx="10" :fill="nodeFill(node)" :stroke="nodeStroke(node)" :stroke-width="selectedId===node.id?3:1.5" :stroke-dasharray="nodeStatus(node)==='open'?'5 4':undefined"/>
            <text :x="node.x+16" :y="node.y+27" :fill="nodeStatus(node)==='open'?'#925807':nodeStatus(node)==='legacy'?'#604b82':'#263449'" font-family="Segoe UI, Microsoft YaHei, sans-serif" font-size="15" font-weight="600">{{ node.title||entities[node.entity].title }}</text>
            <text v-for="(line,index) in subtitleLines(node)" :key="index" :x="node.x+16" :y="node.y+49+index*17" fill="#5b687b" font-family="Segoe UI, Microsoft YaHei, sans-serif" font-size="12.5">{{ line }}</text>
          </g>
          <text class="review-export-note" x="32" :y="topic.height-17" fill="#607086" font-size="12" font-family="Segoe UI, Microsoft YaHei, sans-serif">{{ topic.takeaway }}</text>
        </svg>
      </div>
      <p class="review-takeaway">{{ topic.takeaway }}</p>
    </section>
    <div class="review-detail-grid">
      <section class="review-detail-card review-node-detail" aria-live="polite" data-testid="business-node-detail">
        <div class="review-detail-title">
          <div><span class="review-small-label">当前节点</span><h3>{{ definition.name }}</h3><span class="review-node-term">{{ definition.title }}</span></div>
          <el-tag :type="definition.status==='open'?'warning':definition.status==='legacy'?'info':'success'" size="small">{{ statusLabel(definition.status) }}</el-tag>
        </div>
        <p class="review-node-definition">{{ definition.definition }}</p>
        <div class="review-node-example"><h4>举个例子</h4><p>{{ definition.example }}</p></div>
        <h4>{{ definition.status==='open'?'待确认与当前处理':definition.status==='legacy'?'保留规则':'关键规则' }}</h4>
        <ul><li v-for="rule in definition.rules" :key="rule">{{ rule }}</li></ul>
        <template v-if="definition.links"><h4>对应原型页面</h4><div class="review-detail-links"><router-link v-for="link in definition.links" :key="link[1]" :to="'/commercialization/'+link[1]" target="_blank" rel="noopener">{{ link[0] }} <span aria-hidden="true">↗</span></router-link></div></template>
      </section>
      <section class="review-detail-card"><span class="review-small-label">关系约束</span><h3>{{ topic.name }}中的关键关系</h3><table class="review-relation-table"><thead><tr><th>对象 / 关系</th><th>结构</th><th>业务含义</th></tr></thead><tbody><tr v-for="(relation,index) in topic.relations" :key="index"><td>{{ relation[0] }}</td><td>{{ relation[1] }}</td><td>{{ relation[2] }}</td></tr></tbody></table></section>
    </div>
    <section class="review-live-card">
      <el-collapse v-model="liveExpanded"><el-collapse-item name="live" title="核对当前 Demo 配置 · 区分新定义与历史快照"><p class="review-live-intro">上方关系图表达新业务定义。下方读取当前已发布配置作为评审参考；历史模型的 ALL、次数和通用余额不会被当作新规则。</p><p v-if="liveLoading" role="status">读取配置参考…</p><div v-if="liveErrors.length" class="review-live-error"><p v-for="error in liveErrors" :key="error">{{ error }}</p><el-button size="small" @click="reload">重试读取配置</el-button></div><div class="review-reference-grid">
        <article><h4>权益与内容 Scope</h4><p v-if="catalog!==null">{{ catalog.filter(item=>item.type==='content_access').length }} 个内容权益 · {{ catalog.filter(item=>item.type==='feature_access').length }} 个功能权益 · {{ catalog.filter(item=>item.type==='consumable_credits').length }} 个额度类型示例</p><p v-else>权益目录尚未读取。</p><div class="review-reference-scroll"><table v-if="scopes!==null" class="review-relation-table"><thead><tr><th>内容权益</th><th>具体范围</th><th>状态</th></tr></thead><tbody><tr v-for="scope in scopes" :key="scope.entitlementCode+scope.code"><td>{{ itemName(scope.entitlementCode) }}</td><td>{{ scope.name }}</td><td>{{ scope.status }}</td></tr></tbody></table></div></article>
        <article><h4>已发布 Suit 与版本</h4><label class="review-select-label">选择一个当前套餐<el-select v-model="selectedSuitId" :popper-append-to-body="false" @change="loadSuit"><el-option v-for="suit in suits||[]" :key="suit.id" :label="suit.name" :value="suit.id"/></el-select></label><p v-if="suitLoading">读取套餐快照…</p><p v-if="suitError" class="review-live-error">{{ suitError }}</p><template v-if="liveSuit"><p><el-tag size="mini" :type="liveSuit.published&&liveSuit.published.modelVersion===2?'success':'info'">{{ liveSuit.published?'Published v'+liveSuit.publishedVersion:'未发布草稿' }}</el-tag> {{ liveSuit.published&&liveSuit.published.modelVersion===2?'新三类权益模型':liveSuit.published?'历史模型，已购版本保留':'尚未产生用户授权' }}</p><p v-if="liveSuit.hasDraft">另有草稿；草稿不改变当前已发布版本。</p><dl class="review-facts"><dt>访问项</dt><dd>{{ liveSuit.published?liveSuit.published.items.length:'—' }}</dd><dt>额度规则</dt><dd>{{ liveSuit.published?liveSuit.published.modelVersion===2?(liveSuit.published.creditGrants||[]).map(creditGrantLabel).join('；')||'无发放规则':legacyBenefit(liveSuit.published.creditBenefit):'待发布' }}</dd></dl><router-link :to="'/commercialization/suits/'+liveSuit.id" target="_blank" rel="noopener">打开该套餐配置 ↗</router-link></template></article>
        <article><h4>商品与 SKU</h4><label class="review-select-label">选择一个当前商品<el-select v-model="selectedProductId" :popper-append-to-body="false"><el-option v-for="product in products||[]" :key="product.id" :label="product.name" :value="product.id"/></el-select></label><template v-if="liveProduct"><dl class="review-facts"><dt>类型</dt><dd>{{ liveProduct.kind==='membership'?'Membership Product':'Credit Product' }}</dd><dt>关联</dt><dd>{{ liveProduct.kind==='membership'?suitName(liveProduct.suitId):creditTypeLabel(liveProduct.credits.creditType||'LEGACY_CREDIT') }}</dd><dt>版本</dt><dd>Published v{{ liveProduct.version }}</dd><dt>SKU</dt><dd>{{ liveProduct.skus.length }} 个渠道规格</dd></dl><p v-if="liveProduct.kind==='credits'">只产生该类型额度，不增加会员或功能权限。</p><router-link :to="'/commercialization/products/'+liveProduct.id" target="_blank" rel="noopener">打开商品与 SKU ↗</router-link></template></article>
        <article><h4>订单的实际购买快照</h4><label class="review-select-label">选择一个已有订单<el-select v-model="selectedOrderId" :popper-append-to-body="false"><el-option v-for="order in orders||[]" :key="order.id" :label="order.product.name+' · '+order.userName+' · '+order.status" :value="order.id"/></el-select></label><template v-if="liveOrder"><dl class="review-facts"><dt>商品</dt><dd>{{ liveOrder.product.name }} · v{{ liveOrder.productVersion||liveOrder.product.version||'快照' }}</dd><dt>SKU</dt><dd>{{ liveOrder.sku.id }}</dd><dt>购买金额</dt><dd>{{ money(liveOrder.sku.priceCents,liveOrder.sku.currency) }} · Demo 价格</dd><dt>权益版本</dt><dd>{{ liveOrder.suit?liveOrder.suit.config.name+' v'+liveOrder.suit.version:'额度订单，不关联 Suit' }}</dd><dt>支付 / 履约</dt><dd>{{ liveOrder.status }} / {{ liveOrder.fulfillment }}</dd></dl></template><p v-else-if="orders!==null&&!orders.length">当前没有订单；关系定义不依赖造一笔订单展示。</p><router-link to="/commercialization/orders" target="_blank" rel="noopener">打开订单记录 ↗</router-link></article>
      </div></el-collapse-item></el-collapse>
    </section>
    <section class="review-open-panel"><div><h3>评审待定项 · Open</h3><p>讨论可以围绕这些节点展开；本视图不会把待定项自动变成业务规则。</p></div><div class="review-open-grid"><button v-for="item in openItems" :key="item.id" type="button" :data-testid="'review-open-'+item.id" @click="openDecision(item.entity)"><span>{{ item.id }}</span><strong>{{ item.name }}</strong><small>{{ item.boundary }}</small></button></div></section>
  </section>
</template>
<script>
import {entities,topics,openItems} from './model.cjs'
import {getCatalog,getSuits,getSuit} from '@/api/commercialization'
import {listConfigs,listOrders,getContentScopes,money} from '@/api/commerce'
import {creditTypeLabel,creditGrantLabel} from '@/utils/entitlements'
export default {
  name:'BusinessReview',
  data(){const topic=topics.find(item=>item.id===this.$route.query.topic)||topics[0];return {entities,topics,openItems,topicId:topic.id,selectedId:topic.nodes.some(node=>node.id===this.$route.query.node)?this.$route.query.node:topic.initial,zoom:null,presenting:false,feedback:'',shareFallback:'',liveExpanded:[],liveLoading:false,liveErrors:[],catalog:null,scopes:null,suits:null,products:null,orders:null,selectedSuitId:'',selectedProductId:'',selectedOrderId:'',liveSuit:null,suitLoading:false,suitError:'',loadSequence:0,suitSequence:0}},
  computed:{
    topic(){return topics.find(item=>item.id===this.topicId)},
    selectedNode(){return this.topic.nodes.find(node=>node.id===this.selectedId)},
    definition(){return entities[this.selectedNode.entity]},
    edges(){return this.topic.edges.map(edge=>this.layoutEdge(edge))},
    liveProduct(){const record=(this.products||[]).find(item=>item.id===this.selectedProductId);return record&&record.published?{...record.published,version:record.publishedVersion,id:record.id}:null},
    liveOrder(){return (this.orders||[]).find(item=>item.id===this.selectedOrderId)||null}
  },
  created(){this.reload();window.addEventListener('keydown',this.onKeydown)},
  beforeDestroy(){this.loadSequence++;this.suitSequence++;window.removeEventListener('keydown',this.onKeydown)},
  methods:{
    money,creditTypeLabel,creditGrantLabel,
    statusLabel(status){return status==='open'?'Open · 待定':status==='legacy'?'历史兼容':'已确认'},
    selectTopic(id){this.topicId=id;this.selectedId=this.topic.initial;this.zoom=null;this.feedback='';this.shareFallback='';this.$nextTick(()=>{const canvas=this.$el.querySelector('.review-diagram-scroll');if(canvas){canvas.scrollLeft=0;canvas.scrollTop=0}})},
    selectNode(id){this.selectedId=id;this.feedback='';this.shareFallback=''},
    openDecision(entity){this.selectTopic('versions');this.selectNode(entity);this.$nextTick(()=>this.$el.querySelector('.review-topic-heading').scrollIntoView({block:'start',behavior:'smooth'}))},
    nodeStatus(node){return entities[node.entity].status||'confirmed'},
    nodeLabel(node){return (node.title||entities[node.entity].title)+'，'+(node.subtitle||entities[node.entity].subtitle)+'，'+this.statusLabel(this.nodeStatus(node))},
    nodeFill(node){return this.nodeStatus(node)==='open'?'#fff8e8':this.nodeStatus(node)==='legacy'?'#f5f1fa':this.selectedId===node.id?'#ecf5ff':'#f8fbff'},
    nodeStroke(node){return this.nodeStatus(node)==='open'?'#c99136':this.nodeStatus(node)==='legacy'?'#a08cbd':this.selectedId===node.id?'#2474c8':'#b9cce2'},
    wrapText(text,maxWidth){const lines=[];let line='',width=0;for(const character of text){const next=/[\u0000-\u007f]/.test(character)?6.6:12.5;if(width+next>maxWidth&&line){lines.push(line);line='';width=0}line+=character;width+=next}if(line)lines.push(line);return lines},
    subtitleLines(node){return this.wrapText(node.subtitle||entities[node.entity].subtitle,node.width-32)},
    layoutEdge(edge){if(edge.path){const lines=this.wrapText(edge.label,edge.labelWidth||180);return {...edge,lines,labelY:edge.labelY-(lines.length-1)*15}}const from=this.topic.nodes.find(node=>node.id===edge.from),to=this.topic.nodes.find(node=>node.id===edge.to);const dx=to.x-from.x,dy=to.y-from.y;let path,labelX,labelY,labelWidth=220;if(Math.abs(dy)<100){const right=dx>=0,startX=right?from.x+from.width:from.x,endX=right?to.x:to.x+to.width,startY=from.y+from.height/2,endY=to.y+to.height/2,middle=(startX+endX)/2;path=`M ${startX} ${startY} H ${middle} V ${endY} H ${endX}`;labelX=middle;labelY=Math.min(startY,endY)-13;labelWidth=Math.max(72,Math.abs(endX-startX)-14)}else{const down=dy>0,startX=from.x+from.width/2,endX=to.x+to.width/2,startY=down?from.y+from.height:from.y,endY=down?to.y:to.y+to.height,middle=(startY+endY)/2;path=`M ${startX} ${startY} V ${middle} H ${endX} V ${endY}`;labelX=(startX+endX)/2;labelY=middle-9}const lines=this.wrapText(edge.label,labelWidth);return {...edge,path,labelX,labelY:labelY-(lines.length-1)*15,lines}},
    edgeActive(edge){return edge.from===this.selectedId||edge.to===this.selectedId},
    edgeColor(edge){return edge.status==='open'?'#b77412':this.edgeActive(edge)?'#2474c8':'#9caabd'},
    changeZoom(delta){const current=this.zoom===null?1:this.zoom;this.zoom=Math.max(0.75,Math.min(1.5,current+delta))},
    togglePresentation(){this.presenting=!this.presenting;this.$nextTick(()=>{if(!this.presenting&&this.$refs.presentButton)this.$refs.presentButton.$el.focus()})},
    onKeydown(event){
      if(!this.presenting)return
      if(event.key==='Escape'){this.presenting=false;this.$nextTick(()=>this.$refs.presentButton.$el.focus());return}
      if(event.key!=='Tab')return
      const controls=[...this.$el.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),[tabindex="0"]')].filter(element=>{const box=element.getBoundingClientRect();return box.width>0&&box.height>0&&!element.closest('[aria-hidden="true"]')})
      if(!controls.length)return
      const first=controls[0],last=controls[controls.length-1],active=document.activeElement,outside=!this.$el.contains(active)
      if(event.shiftKey&&(active===first||outside)){event.preventDefault();last.focus()}
      else if(!event.shiftKey&&(active===last||outside)){event.preventDefault();first.focus()}
    },
    currentLink(){const url=new URL(window.location.href);url.hash='/commercialization/overview?'+new URLSearchParams({tab:'logic',topic:this.topicId,node:this.selectedId}).toString();return url.href},
    async copyLink(){const url=this.currentLink();try{await navigator.clipboard.writeText(url);this.feedback='已复制当前主题和节点的链接。';this.shareFallback=''}catch(_){this.shareFallback=url;this.feedback='可从下面复制当前视图链接。'}},
    exportSvg(){const svg=this.$refs.graphSvg.cloneNode(true);svg.removeAttribute('style');svg.setAttribute('width',this.topic.width);svg.setAttribute('height',this.topic.height);svg.querySelectorAll('[tabindex]').forEach(node=>node.removeAttribute('tabindex'));const data='<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(svg);const url=URL.createObjectURL(new Blob([data],{type:'image/svg+xml;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='SunnyFit-business-'+this.topicId+'.svg';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);this.feedback='已导出当前关系图，包含关系说明与状态标记。'},
    itemName(code){return (this.catalog||[]).find(item=>item.code===code)?.name||code},
    suitName(id){return (this.suits||[]).find(item=>item.id===id)?.name||id},
    legacyBenefit(benefit){return benefit&&benefit.amount?`${benefit.amount} Legacy Credits · ${benefit.cadence} · ${benefit.validityDays} days`:'无历史额度福利'},
    async reload(){const sequence=++this.loadSequence;this.liveLoading=true;this.liveErrors=[];const requests=[['catalog','权益目录',getCatalog],['suits','权益套餐',getSuits],['products','商品',()=>listConfigs('products')],['scopes','内容 Scope',getContentScopes],['orders','订单',listOrders]];const results=await Promise.allSettled(requests.map(entry=>entry[2]()));if(sequence!==this.loadSequence)return;results.forEach((result,index)=>{if(result.status==='fulfilled')this[requests[index][0]]=result.value;else this.liveErrors.push(requests[index][1]+'读取失败：'+result.reason.message)});if(this.suits&&!this.suits.some(item=>item.id===this.selectedSuitId))this.selectedSuitId=(this.suits.find(item=>item.id==='premium')||this.suits[0]||{}).id||'';if(this.products&&!this.products.some(item=>item.id===this.selectedProductId))this.selectedProductId=(this.products.find(item=>item.published&&item.published.kind==='membership')||this.products[0]||{}).id||'';if(this.orders&&!this.orders.some(item=>item.id===this.selectedOrderId))this.selectedOrderId=(this.orders[0]||{}).id||'';this.liveLoading=false;await this.loadSuit()},
    async loadSuit(){const sequence=++this.suitSequence;this.liveSuit=null;this.suitError='';if(!this.selectedSuitId)return;this.suitLoading=true;try{const suit=await getSuit(this.selectedSuitId);if(sequence===this.suitSequence)this.liveSuit=suit}catch(error){if(sequence===this.suitSequence)this.suitError=error.message}finally{if(sequence===this.suitSequence)this.suitLoading=false}}
  }
}
